class Solution {
public:
    string kthLuckyNumber(int k) {
        long long val = (long long)k + 1;
        string res = "";
        while (val > 1) {
            res += (val & 1) ? '7' : '4';
            val >>= 1;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public String kthLuckyNumber(int k) {
        long val = (long) k + 1;
        StringBuilder sb = new StringBuilder();
        while (val > 1) {
            sb.append((val & 1) == 1 ? '7' : '4');
            val >>= 1;
        }
        return sb.reverse().toString();
    }
}

