var kthLuckyNumber = function(k) {
    let val = BigInt(k) + 1n;
    let res = [];
    while (val > 1n) {
        res.push((val & 1n) === 1n ? '7' : '4');
        val >>= 1n;
    }
    return res.reverse().join('');
};
